package com.tianji.qimen

import java.io.File
import java.time.*
import kotlinx.serialization.json.*
import org.junit.Assert.*
import org.junit.Test

class TraditionalCoreTest {
    private val core = QimenCore()
    private fun at(local: String, zone: String = "Asia/Hong_Kong") = core.calculateChart(LocalDateTime.parse(local).atZone(ZoneId.of(zone)).toInstant(), zone)
    @Test fun independentPublishedShanghaiChart() {
        // R3: published worked example, not output generated by TianJi or R6.
        val c = at("2027-02-06T10:00:00")
        assertEquals("TRADITIONAL", c.status)
        assertEquals(listOf("丁未", "壬寅", "丙辰", "癸巳"), listOf("year_ganzhi", "month_ganzhi", "day_ganzhi", "hour_ganzhi").map { c.calendar[it] })
        assertEquals("陽遁", c.dun_type); assertEquals(5, c.ju_number)
        assertEquals("中元", c.calendar["yuan"]); assertEquals("甲寅", c.calendar["fu_tou"])
        assertEquals("天柱", c.calendar["duty_star"]); assertEquals("1", c.calendar["duty_star_palace"])
        assertEquals("驚門", c.calendar["duty_door"]); assertEquals("7", c.calendar["duty_door_palace"])
        val earth = listOf("癸", "丁", "丙", "乙", "戊", "己", "庚", "辛", "壬")
        val heaven = listOf("庚", "乙", "癸", "辛", null, "丁", "壬", "己", "丙")
        val star = listOf("天柱", "天輔", "天蓬", "天任", null, "天芮", "天英", "天心", "天沖")
        val door = listOf("休門", "死門", "傷門", "杜門", null, "開門", "驚門", "生門", "景門")
        val god = listOf("值符", "玄武", "太陰", "六合", null, "九天", "九地", "螣蛇", "白虎")
        c.palaces.forEachIndexed { i, p ->
            assertEquals("earth $i", earth[i], p.earth_stem?.substringBefore("、"))
            assertEquals("heaven $i", heaven[i], p.heaven_stem?.substringBefore("、"))
            assertEquals("star $i", star[i], p.star?.substringBefore("、"))
            assertEquals(door[i], p.door); assertEquals(god[i], p.deity)
        }
        // Hosting is documented separately: the source table shows only main stems.
        assertEquals("天芮、天禽", c.palaces[5].star); assertEquals("丁、戊", c.palaces[5].heaven_stem)
        assertEquals("丁、戊", c.palaces[1].earth_stem)
        val fixture = File(System.getProperty("tianji.root"), "contracts/fixtures/traditional-chart.json")
        fixture.writeText(core.canonical(c))
    }
    @Test fun externalCrossImplementationCorpus() {
        val root = Json.parseToJsonElement(File(System.getProperty("tianji.root"), "contracts/fixtures/cross-engine-charts.json").readText()).jsonObject
        val cases = root.getValue("cases").jsonArray
        assertTrue(cases.size >= 100)
        cases.forEach { element ->
            val e = element.jsonObject
            fun v(key: String) = e.getValue(key).jsonPrimitive.content
            val c = at(v("local").replace(' ', 'T'))
            assertEquals(v("local"), v("day"), c.calendar["day_ganzhi"])
            assertEquals(v("local"), v("hour"), c.calendar["hour_ganzhi"])
            assertEquals(v("local"), v("dun"), c.dun_type)
            assertEquals(v("local"), v("ju").toInt(), c.ju_number)
            assertEquals(v("local"), v("yuan"), c.calendar["yuan"])
            e.getValue("palaces").jsonArray.forEachIndexed { i, p ->
                val expected = p.jsonObject
                val actual = c.palaces[i]
                val fields = mapOf("door" to actual.door, "star" to actual.star?.substringBefore("、"), "deity" to actual.deity, "heaven_stem" to actual.heaven_stem, "earth_stem" to actual.earth_stem)
                fields.forEach { (key, value) -> assertEquals("${v("local")} palace ${i+1} $key", expected.getValue(key).jsonPrimitive.contentOrNull, value) }
            }
        }
    }
    @Test fun hko2026IndependentMajorSolarTerms() {
        // R5: published Hong Kong clock times, precision one minute. Tolerance 90s.
        val terms = listOf("01-20T09:45" to "大寒", "02-18T23:52" to "雨水", "03-20T22:46" to "春分", "04-20T09:39" to "穀雨", "05-21T08:37" to "小滿", "06-21T16:25" to "夏至", "07-23T03:13" to "大暑", "08-23T10:19" to "處暑", "09-23T08:05" to "秋分", "10-23T17:38" to "霜降", "11-22T15:23" to "小雪", "12-22T04:50" to "冬至")
        terms.forEach { (clock, name) ->
            val official = LocalDateTime.parse("2026-$clock").toInstant(ZoneOffset.ofHours(8))
            val c = core.calculateChart(official.plusSeconds(120), "Asia/Hong_Kong")
            assertEquals(name, c.calendar["solar_term"])
            val calculated = Instant.parse(c.calendar.getValue("solar_term_start_utc"))
            assertTrue("$name $calculated vs $official", kotlin.math.abs(Duration.between(official, calculated).seconds) <= 90)
            val before = core.calculateChart(calculated.minusSeconds(1), "America/Los_Angeles")
            val after = core.calculateChart(calculated, "America/Los_Angeles")
            assertNotEquals(name, before.calendar["solar_term"]); assertEquals(name, after.calendar["solar_term"])
            assertTrue(after.warnings.contains("NEAR_SOLAR_TERM_BOUNDARY"))
        }
    }
    @Test fun ziHourMidnightAndLeapDay() {
        val a = at("2024-02-29T22:59:59"); val b = at("2024-02-29T23:00:00"); val c = at("2024-03-01T00:00:00")
        assertNotEquals(a.calendar["day_ganzhi"], b.calendar["day_ganzhi"])
        assertEquals(b.palaces, c.palaces); assertEquals(b.calendar["day_ganzhi"], c.calendar["day_ganzhi"])
        assertEquals("戊午", at("2000-01-01T12:00:00").calendar["day_ganzhi"])
        assertEquals("甲子", at("1949-10-01T12:00:00").calendar["day_ganzhi"])
    }
    @Test fun civilZoneUsesSameAbsoluteSolarTermAndDistinctLocalPillars() {
        val i = Instant.parse("2026-10-12T01:00:00Z")
        val hk = core.calculateChart(i, "Asia/Hong_Kong"); val la = core.calculateChart(i, "America/Los_Angeles")
        assertEquals(hk.calendar["solar_term_start_utc"], la.calendar["solar_term_start_utc"])
        assertEquals(hk.calendar["year_ganzhi"], la.calendar["year_ganzhi"])
        assertNotEquals(hk.calendar["day_ganzhi"], la.calendar["day_ganzhi"])
        assertNotEquals(hk.input_hash, la.input_hash)
        assertEquals(hk, QimenCore().calculateChart(i, "Asia/Hong_Kong"))
    }
    @Test fun dstGapRejectedAndOverlapBothInstantsPreserved() {
        val zone = ZoneId.of("America/Los_Angeles")
        assertTrue(ChartTime.candidates(LocalDate.of(2026,3,8), LocalTime.of(2,30), zone).isEmpty())
        val two = ChartTime.candidates(LocalDate.of(2026,11,1), LocalTime.of(1,30), zone)
        assertEquals(2, two.size); assertEquals(3600, Duration.between(two[0], two[1]).seconds)
        val charts = two.map { core.calculateChart(it, zone.id) }
        assertEquals(charts[0].palaces, charts[1].palaces); assertNotEquals(charts[0].input_hash, charts[1].input_hash)
    }
    @Test fun exhaustiveYearInvariantsAndCenterCases() {
        var centerDuty = 0; var centerHour = 0; var centerDoor = 0
        var date = LocalDate.of(2026, 1, 1)
        repeat(365) {
            for (hour in 0..22 step 2) {
                val c = at("${date}T${hour.toString().padStart(2,'0')}:30:00")
                assertEquals((1..9).toList(), c.palaces.map { it.index })
                val outer = c.palaces.filter { it.index != 5 }
                assertEquals(8, outer.map { it.door }.toSet().size)
                assertEquals(8, outer.map { it.deity }.toSet().size)
                assertEquals(9, outer.flatMap { it.star!!.split("、") }.toSet().size)
                assertEquals(9, outer.flatMap { it.heaven_stem!!.split("、") }.toSet().size)
                val god = outer.single { it.deity == "值符" }
                assertTrue(god.star!!.contains(c.calendar.getValue("duty_star")))
                assertEquals(c.calendar["duty_door"], c.palaces[c.calendar.getValue("duty_door_palace").toInt()-1].door)
                assertNull(c.palaces[4].door); assertNull(c.palaces[4].heaven_stem)
                if(c.calendar["duty_origin"] == "5") centerDuty++
                if(c.calendar["duty_star_raw_palace"] == "5") centerHour++
                if(c.calendar["duty_door_raw_palace"] == "5") centerDoor++
            }; date = date.plusDays(1)
        }
        assertTrue(centerDuty > 0 && centerHour > 0 && centerDoor > 0)
    }
    @Test(expected=IllegalArgumentException::class) fun unsupportedDatesFailExplicitly() { at("2200-01-01T12:00:00") }
}
